# -*- coding: utf-8 -*-
import os
import sys
import json
import base64
import subprocess
import time
import urllib.request
import re

def safe_b64decode(b64_str):
    clean = re.sub(r'[^A-Za-z0-9+/=]', '', b64_str)
    missing = len(clean) % 4
    if missing:
        clean += '=' * (4 - missing)
    return base64.b64decode(clean)

def free_port_8000():
    if sys.platform == "win32":
        try:
            out = subprocess.check_output("netstat -ano | findstr :8000", shell=True).decode()
            pids = set()
            for line in out.strip().split('\n'):
                parts = line.split()
                if len(parts) >= 5 and "LISTENING" in line:
                    pids.add(parts[-1])
            for pid in pids:
                if pid != "0":
                    subprocess.run(f"taskkill /F /PID {pid}", shell=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:
            pass

def create_desktop_shortcut():
    if sys.platform == "win32":
        try:
            desktop = os.path.join(os.path.expanduser("~"), "Desktop")
            target = os.path.join(os.getcwd(), "Iniciar_DC_Control.vbs")
            shortcut = os.path.join(desktop, "DC Control.lnk")
            sc_target = target.replace('\\', '\\\\')
            sc_path = shortcut.replace('\\', '\\\\')
            sc_work = os.getcwd().replace('\\', '\\\\')
            vbs_script = f"""
Set WshShell = CreateObject("WScript.Shell")
Set shortcut = WshShell.CreateShortcut("{sc_path}")
shortcut.TargetPath = "{sc_target}"
shortcut.WorkingDirectory = "{sc_work}"
shortcut.Description = "Sistema DC Control v50"
shortcut.Save
"""
            tmp_vbs = os.path.join(os.getcwd(), "temp_shortcut.vbs")
            with open(tmp_vbs, "w") as f:
                f.write(vbs_script)
            subprocess.run(f'cscript //nologo "{tmp_vbs}"', shell=True)
            if os.path.exists(tmp_vbs):
                os.remove(tmp_vbs)
            print("✔️ Acceso directo 'DC Control' creado en el Escritorio.")
        except Exception as e:
            print(f"Aviso al crear acceso directo: {e}")

