def copy_user_logo(target_dir):
    logo_found = None
    for lname in ['logo.png', 'logo.jpg', 'logo.jpeg', 'logo.PNG', 'logo.JPG']:
        if os.path.exists(lname):
            logo_found = lname
            break
    if logo_found:
        print(f"🖼️ Logotipo detectado en {logo_found}. Copiando a carpetas públicas...")
        try:
            for sub in ['', 'public', 'src']:
                dest_fold = os.path.join(target_dir, sub) if sub else target_dir
                if os.path.exists(dest_fold):
                    with open(logo_found, 'rb') as f_in:
                        data = f_in.read()
                    with open(os.path.join(dest_fold, 'logo.png'), 'wb') as f_out:
                        f_out.write(data)
        except Exception as e:
            print(f"Aviso al copiar logo: {e}")

def wait_for_backend(port=8000, timeout=25):
    start = time.time()
    while time.time() - start < timeout:
        try:
            req = urllib.request.urlopen(f"http://127.0.0.1:{port}/api/projects", timeout=2)
            if req.getcode() == 200:
                return True
        except Exception:
            pass
        time.sleep(1)
    return False

def install_and_run():
    print("="*70)
    print("🚀  INSTALADOR Y EJECUTABLE UNIFICADO - DC CONTROL V50 (v13)         🚀")
    print("="*70)

    free_port_8000()
    target_dir = extract_files()
    copy_user_logo(target_dir)
    create_desktop_shortcut()

    reqs = ["fastapi", "uvicorn", "psycopg2-binary", "pandas", "python-docx", "matplotlib", "requests", "pydantic"]
    print("\n📦 Verificando dependencias de Python...")
    for req in reqs:
        try:
            subprocess.run([sys.executable, "-m", "pip", "install", req, "--quiet"], check=False)
        except Exception:
            pass

    print("\n📦 Instalando dependencias de Node.js (npm install)...")
    npm_cmd = "npm.cmd" if sys.platform == "win32" else "npm"
    try:
        subprocess.run([npm_cmd, "install", "--foreground-scripts"], cwd=target_dir, shell=True)
    except Exception as e:
        print(f"Aviso npm: {e}")

    print("\n⚡ Iniciando servidor Backend FastAPI en segundo plano (Puerto 8000)...")
    backend_dir = os.path.join(target_dir, "backend")
    backend_process = subprocess.Popen([sys.executable, "-m", "uvicorn", "main:app", "--host", "127.0.0.1", "--port", "8000"], cwd=backend_dir)

    print("⏳ Esperando respuesta del Backend FastAPI...")
    if wait_for_backend(8000):
        print("✔️ Backend FastAPI respondiendo correctamente en http://127.0.0.1:8000")
    else:
        print("⚠️ El servidor Backend tardó más de lo esperado en iniciar.")

    print("\n🎨 Iniciando cliente Frontend Vite / Electron (Puerto 5173)...")
    try:
        subprocess.run([npm_cmd, "start"], cwd=target_dir, shell=True)
    except KeyboardInterrupt:
        print("\nCerrando aplicación...")
    finally:
        try:
            backend_process.terminate()
        except Exception:
            pass

if __name__ == "__main__":
    install_and_run()
